// The platform's fields (6 Nov 2026, his request: «create all the rest of the fields … inside fields categories and
// inside categories the agents»). A field is a profession or a side of life; its categories are the areas that
// profession works in; every ready agent belongs to one category of one field. Shared by the client (library panel,
// editor, builder) and the server (the builder's design prompt and its validation).
export type FieldId = 'legal' | 'finance' | 'hr' | 'marketing' | 'operations' | 'product' | 'healthcare' | 'education' | 'languages' | 'creative' | 'communication'
  | 'compliance' | 'business' | 'data' | 'support' | 'realestate' | 'research' | 'public' | 'hospitality' | 'shipping' | 'insurance'
  | 'it' | 'finserv' | 'retail' | 'manufacturing' | 'sustainability' | 'startups' | 'projects' | 'everyday';
export type FieldCategory = {
  id: string; name: string;
  /** A muted ink, dark enough to read as text on its own 12 % tint (the card chip and the panel row). */
  color: string;
  /** A lucide icon name (src/components/library.tsx maps it; an unknown name draws «Layers»). */
  icon: string;
  /** What the area covers, for the writers of agents and for the builder's design prompt. */
  hint: string;
};
export type Field = {
  id: FieldId; name: string; blurb: string;
  /** The panel's heading for the categories («Practice areas») and the editor's label for one («Practice area»). */
  areas: string; area: string;
  /** Four one-line ideas the builder offers for a new agent in this field. */
  ideas: readonly string[];
  categories: readonly FieldCategory[];
};

