export const FIELD_IDS: readonly FieldId[] = FIELDS.map(field => field.id);
export const isFieldId = (value: unknown): value is FieldId => typeof value === 'string' && (FIELD_IDS as readonly string[]).includes(value);
export const fieldById = (id: string | undefined | null): Field | undefined => FIELDS.find(field => field.id === id);
/** Every category id of every field, for validation; ids are unique across fields. */
export const ALL_CATEGORY_IDS: readonly string[] = FIELDS.flatMap(field => field.categories.map(category => category.id));
const byCategory = new Map<string, { field: Field; category: FieldCategory }>();
for (const field of FIELDS) for (const category of field.categories) byCategory.set(category.id, { field, category });
/** The field and the category a category id belongs to. */
export const categoryOf = (id: string) => byCategory.get(id);
export const categoryBelongs = (field: string, category: string) => byCategory.get(category)?.field.id === field;
